"""Create one offline HTML review of the real game; no APK or network upload."""
from pathlib import Path
import base64,json,re,hashlib,shutil
ROOT=Path(__file__).resolve().parents[1]
b64=lambda b:base64.b64encode(b).decode('ascii')
h=(ROOT/'game/index.html').read_text()
h=h.replace('ODYSSEY LANDSCAPE v26','ANTEPRIMA v27')
css=(ROOT/'game/landscape-v24.css').read_text()+'\n'+(ROOT/'tools/preview-v27.css').read_text()
js=(ROOT/'game/landscape-v24.js').read_text()
js=js.replace('assets/nexa-guardian.webp','data:image/webp;base64,'+b64((ROOT/'game/assets/nexa-guardian.webp').read_bytes()))
h=h.replace('<link rel="stylesheet" href="landscape-v24.css">','<style>'+css+'</style>')
h=h.replace('<script defer src="landscape-v24.js"></script>','<script>'+js+'</script><script>'+(ROOT/'tools/preview-v27.js').read_text()+'</script>')
h=h.replace('<head>','<head><script>window.__BN_HTML_PREVIEW__=true;</script>',1)
icon='data:image/png;base64,'+b64((ROOT/'artwork/blastnexa-play-icon-v26.png').read_bytes())
header='''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>BlastNexa · Anteprima monete, linee e inviti</title><link rel="icon" href="ICON"><style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#091321;color:#edf9f7;font-family:system-ui,sans-serif}body{display:flex;flex-direction:column;min-height:100dvh}header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 18px;background:#0e1e2c;border-bottom:1px solid #29414a}header img{width:35px;height:35px;border-radius:10px}header .brand{display:flex;align-items:center;gap:11px}header strong{display:block;font-size:14px;letter-spacing:.06em}header small{font-size:10px;color:#9ebdbb}.tag{font-size:10px;border:1px solid #75bba780;border-radius:20px;color:#afffd6;padding:6px 10px;background:#0f382f}nav{display:flex;justify-content:center;align-items:center;gap:7px;padding:10px 10px 6px;flex-wrap:wrap}button{font:inherit;cursor:pointer;border:1px solid #52726f;border-radius:8px;background:#173b3a;color:#dcfff0;font-size:11px;font-weight:750;padding:8px 12px}button:focus-visible{outline:3px solid #b5ff6a;outline-offset:2px}button[disabled]{opacity:.45;cursor:wait}button[data-action="win"]{background:#9cffc9;color:#103a38;border-color:#9cffc9}#stage{position:relative;overflow:hidden;align-self:center;margin:8px auto 0;border-radius:12px;box-shadow:0 0 0 1px #4b6d6a,0 18px 60px #0008;background:#151d22}iframe{display:block;width:800px;height:360px;border:0;transform-origin:top left}footer{text-align:center;font-size:10px;line-height:1.5;color:#9fb9bf;padding:11px 18px 14px}footer b{color:#d2e7d9}#rotate{display:none;color:#bfffcb;font-size:11px;text-align:center;padding:10px 14px 0}#iconSheet{position:fixed;inset:0;z-index:10;background:#091321f7;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:25px;gap:17px}#iconSheet[hidden]{display:none}#iconSheet img{width:min(65vw,320px);border-radius:24%;box-shadow:0 12px 70px #8df51622}#iconSheet strong{font-size:20px}#iconSheet small{font-size:12px;color:#bed3d5;text-align:center}@media(orientation:portrait){#rotate{display:block}header{padding:11px 13px}.tag{font-size:8px}nav{gap:6px;padding-top:14px}button{font-size:10px;padding:9px 10px}footer{font-size:10px}}@media(orientation:landscape) and (max-height:500px){header{padding:5px 12px}header img{width:25px;height:25px}header strong{font-size:11px}header small{font-size:8px}.tag{padding:3px 8px;font-size:8px}nav{padding:5px;gap:5px}button{padding:4px 9px;font-size:9px}footer{padding:5px 12px;font-size:8px}#stage{margin-top:4px;border-radius:5px}}
</style></head><body><header><div class="brand"><img src="ICON" alt="Nuova icona neon"><div><strong>BLASTNEXA</strong><small>Anteprima interattiva · Monete, linee e inviti</small></div></div><span class="tag">SOLO HTML · v27</span></header><div id="rotate">Ruota il telefono in orizzontale per vedere il gioco più grande.</div><nav aria-label="Strumenti di anteprima"><button data-action="win" disabled>PROVA VINCITA</button><button data-action="empty" disabled>PROVA VIDEO +100</button><button data-action="invites" disabled>INVITI AUTOMATICI</button><button data-action="reset" disabled>SALDO 100</button><button id="showIcon">NUOVA ICONA</button><button id="full">SCHERMO INTERO</button></nav><main id="stage"><iframe id="game" title="BlastNexa: slot interattiva con monete giornaliere"></iframe></main><footer><b>100 monete ogni nuovo giorno · x1 = 1 moneta per linea · Vincite in vite</b><br>Video e notifiche sono dimostrativi nell’HTML. I pulsanti PROVA agiscono solo su questa anteprima.</footer><section id="iconSheet" hidden aria-label="Nuova icona app"><img src="ICON" alt="Icona con blocchi neon lime, ciano e fucsia"><strong>Una scarica di Nexa</strong><small>Blocchi neon lime e ciano, accento fucsia, fondo viola acceso.</small><button id="closeIcon">TORNA ALLA SLOT</button></section>'''
footer='''<script>
const frame=document.getElementById('game'),stage=document.getElementById('stage');
const payload=document.getElementById('gamePayload').textContent.trim();
frame.srcdoc=new TextDecoder().decode(Uint8Array.from(atob(payload),c=>c.charCodeAt(0)));
function fit(){const isFull=!!document.fullscreenElement;const taken=isFull?0:document.querySelector('header').offsetHeight+document.querySelector('nav').offsetHeight+document.querySelector('footer').offsetHeight+document.getElementById('rotate').offsetHeight+25;const width=isFull?innerWidth:innerWidth-20;const available=Math.max(170,innerHeight-taken);const scale=Math.max(.2,Math.min(width/800,available/360,1.8));frame.style.transform='scale('+scale+')';stage.style.width=(800*scale)+'px';stage.style.height=(360*scale)+'px';}
window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',fit);fit();
window.addEventListener('message',e=>{if(e.source===frame.contentWindow&&e.data?.type==='bn-v27-ready')document.querySelectorAll('[data-action]').forEach(b=>b.disabled=false);});
document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{frame.contentWindow.focus();frame.contentWindow.postMessage({type:'bn-v27-review',action:button.dataset.action},'*');});
document.getElementById('showIcon').onclick=()=>{document.getElementById('iconSheet').hidden=false;document.getElementById('closeIcon').focus();};document.getElementById('closeIcon').onclick=()=>{document.getElementById('iconSheet').hidden=true;document.getElementById('showIcon').focus();};
document.getElementById('full').onclick=async()=>{try{if(!document.fullscreenElement){await stage.requestFullscreen();}else await document.exitFullscreen();}catch{}};
</script></body></html>'''
outer=header.replace('\"ICON\"','\"'+icon+'\"')+'<script id="gamePayload" type="application/octet-stream">'+b64(h.encode())+'</script>'+footer
out=ROOT/'game/preview-v27.html';out.write_text(outer)
deliverable=ROOT.parent/'output/BlastNexa_Anteprima_v27.html';deliverable.parent.mkdir(exist_ok=True);shutil.copyfile(out,deliverable)
print(json.dumps({'file':str(deliverable),'bytes':deliverable.stat().st_size,'sha256':hashlib.sha256(deliverable.read_bytes()).hexdigest(),'standalone':True}))
